from ortools.sat.python import cp_model
import json

# Input data
N = 20  # Number of steps to the solution
puzzle_start = [
    [0, 3, 6],
    [2, 4, 8],
    [1, 7, 5]
]

puzzle_end = [
    [1, 2, 3],
    [4, 5, 6],
    [7, 8, 0]
]

# Extracting size and tiles from input
size = len(puzzle_start)
tiles = size * size

# Model definition
model = cp_model.CpModel()

# Decision Variables
# States of the puzzle at each step
puzzle = [[[model.NewIntVar(0, tiles-1, f'puzzle_{s}_{i}_{j}') for j in range(size)] for i in range(size)] for s in range(N+1)]

# Constraints
# Initial and final state constraints
for i in range(size):
    for j in range(size):
        model.Add(puzzle[0][i][j] == puzzle_start[i][j])
        model.Add(puzzle[N][i][j] == puzzle_end[i][j])

# Each tile is in exactly one position at each step
for s in range(N+1):
    tile_positions = {}
    for i in range(size):
        for j in range(size):
            tile = puzzle[s][i][j]
            if tile not in tile_positions:
                tile_positions[tile] = []
            tile_positions[tile].append(1)
    for tile in range(tiles):
        model.Add(sum(tile_positions[tile]) == 1)

# Transition constraints: the empty tile (0) moves to an adjacent tile
for s in range(N):
    for i in range(size):
        for j in range(size):
            if i > 0:
                model.Add(puzzle[s][i][j] == 0).OnlyEnforceIf(puzzle[s+1][i-1][j] != 0)
                model.Add(puzzle[s+1][i-1][j] == 0).OnlyEnforceIf(puzzle[s][i][j] != 0)
            if i < size - 1:
                model.Add(puzzle[s][i][j] == 0).OnlyEnforceIf(puzzle[s+1][i+1][j] != 0)
                model.Add(puzzle[s+1][i+1][j] == 0).OnlyEnforceIf(puzzle[s][i][j] != 0)
            if j > 0:
                model.Add(puzzle[s][i][j] == 0).OnlyEnforceIf(puzzle[s+1][i][j-1] != 0)
                model.Add(puzzle[s+1][i][j-1] == 0).OnlyEnforceIf(puzzle[s][i][j] != 0)
            if j < size - 1:
                model.Add(puzzle[s][i][j] == 0).OnlyEnforceIf(puzzle[s+1][i][j+1] != 0)
                model.Add(puzzle[s+1][i][j+1] == 0).OnlyEnforceIf(puzzle[s][i][j] != 0)

    # Tiles other than the empty tile do not move unless adjacent to the empty tile
    for i in range(size):
        for j in range(size):
            tile = puzzle[s][i][j]
            adjacent_empty = []
            if i > 0:
                adjacent_empty.append(puzzle[s][i-1][j] == 0)
            if i < size - 1:
                adjacent_empty.append(puzzle[s][i+1][j] == 0)
            if j > 0:
                adjacent_empty.append(puzzle[s][i][j-1] == 0)
            if j < size - 1:
                adjacent_empty.append(puzzle[s][i][j+1] == 0)
            model.Add(tile == puzzle[s+1][i][j]).OnlyEnforceIf(~(sum(adjacent_empty) >= 1))

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    steps = []
    for s in range(N+1):
        step = []
        for i in range(size):
            row = []
            for j in range(size):
                row.append(solver.Value(puzzle[s][i][j]))
            step.append(row)
        steps.append(step)
    solution = {'steps': steps}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
