from ortools.sat.python import cp_model
import json
import math

# Input data
locations = [
    (288, 149), (288, 129), (270, 133), (256, 141), (256, 163), (246, 157),
    (236, 169), (228, 169), (228, 148), (220, 164), (212, 172), (204, 159)
]

# Calculate distances between locations
distances = {}
for i in range(len(locations)):
    for j in range(len(locations)):
        if i == j:
            distances[i, j] = 0
        else:
            distances[i, j] = math.sqrt((locations[i][0] - locations[j][0])**2 + (locations[i][1] - locations[j][1])**2)

# Model definition
model = cp_model.CpModel()

# Decision Variables
num_locations = len(locations)
x = {}
for i in range(num_locations):
    for j in range(num_locations):
        x[i, j] = model.NewBoolVar(f'x_{i}_{j}')

# Constraints
for i in range(num_locations):
    model.Add(sum(x[i, j] for j in range(num_locations)) == 1)  # Exactly one city is visited after city i
    model.Add(sum(x[j, i] for j in range(num_locations)) == 1)  # City i is visited exactly once

# Subtour elimination constraints
for i in range(1, num_locations):
    for j in range(1, num_locations):
        if i != j:
            model.Add(x[i, j] + x[j, i] <= 1)

# Create a circuit constraint using a loop to add the subtour elimination constraints for all possible subtours
u = [model.NewIntVar(0, num_locations - 1, f'u_{i}') for i in range(num_locations)]
model.Add(u[0] == 0)
for i in range(1, num_locations):
    for j in range(1, num_locations):
        if i != j:
            model.Add(u[i] - u[j] + num_locations * x[i, j] <= num_locations - 1)

# Objective function
model.Minimize(sum(distances[i, j] * x[i, j] for i in range(num_locations) for j in range(num_locations)))

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    solution = {
        'travel_distance': solver.ObjectiveValue()
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
```

