from ortools.sat.python import cp_model
import json

# Input data
n_teams = 9
n_days = 18

# Model definition
model = cp_model.CpModel()

# Data processing
teams = ['Clem', 'Duke', 'FSU', 'GT', 'UMD', 'UNC', 'NCSt', 'UVA', 'Wake']
mirroring_scheme = [(1, 8), (2, 9), (3, 12), (4, 13), (5, 14), (6, 15), (7, 16), (10, 17), (11, 18)]
rivals = {'Clem': 'GT', 'Duke': 'UNC', 'FSU': None, 'GT': 'Clem', 'UMD': 'UVA', 'UNC': 'Duke', 'NCSt': 'Wake', 'UVA': 'UMD', 'Wake': 'NCSt'}
constrained_matches = [('Wake', 'UNC'), ('Wake', 'Duke'), ('GT', 'UNC'), ('GT', 'Duke')]

# Decision Variables
match_config = {}
for day in range(n_days):
    for team1 in range(n_teams):
        for team2 in range(n_teams):
            match_config[(day, team1, team2)] = model.NewBoolVar(f'd{day}_t{team1}_t{team2}')

where = {}
for day in range(n_days):
    for team in range(n_teams):
        where[(day, team)] = model.NewIntVar(-1, 1, f'd{day}_t{team}')  # -1: away, 0: bye, 1: home

# Constraints
# 1. Mirroring
for (r1, r2) in mirroring_scheme:
    r1 -= 1
    r2 -= 1
    for team1 in range(n_teams):
        for team2 in range(n_teams):
            model.Add(match_config[(r1, team1, team2)] == match_config[(r2, team2, team1)])

# 2. No Two Final Aways
for team in range(n_teams):
    model.Add(where[(n_days-1, team)] != -1)
    model.Add(where[(n_days-2, team)] != -1)

# 3. Home/Away/Bye Pattern Constraints
for team in range(n_teams):
    for day in range(n_days-2):
        model.Add(where[(day, team)] + where[(day+1, team)] + where[(day+2, team)] >= -2)  # No more than 2 away in a row
        model.Add(where[(day, team)] + where[(day+1, team)] + where[(day+2, team)] <= 2)  # No more than 2 home in a row
    for day in range(n_days-3):
        model.Add(where[(day, team)] + where[(day+1, team)] + where[(day+2, team)] + where[(day+3, team)] >= -3)  # No more than 3 away/byes in a row
        model.Add(where[(day, team)] + where[(day+1, team)] + where[(day+2, team)] + where[(day+3, team)] <= 4)  # No more than 4 home/byes in a row

# 4. Weekend Pattern
for team in range(n_teams):
    home_count = sum([model.NewBoolVar(f'wknd_home_t{team}_d{day}') for day in range(1, n_days, 2)])
    away_count = sum([model.NewBoolVar(f'wknd_away_t{team}_d{day}') for day in range(1, n_days, 2)])
    bye_count = sum([model.NewBoolVar(f'wknd_bye_t{team}_d{day}') for day in range(1, n_days, 2)])
    for day in range(1, n_days, 2):
        model.Add(where[(day, team)] == 1).OnlyEnforceIf(home_count.NewBoolVar(f'wknd_home_t{team}_d{day}'))
        model.Add(where[(day, team)] == -1).OnlyEnforceIf(away_count.NewBoolVar(f'wknd_away_t{team}_d{day}'))
        model.Add(where[(day, team)] == 0).OnlyEnforceIf(bye_count.NewBoolVar(f'wknd_bye_t{team}_d{day}'))
    model.Add(home_count == 4)
    model.Add(away_count == 4)
    model.Add(bye_count == 1)

# 5. First Weekends
for team in range(n_teams):
    count = sum([model.NewBoolVar(f'first_wknd_home_or_bye_t{team}_d{day}') for day in range(1, 10, 2)])
    for day in range(1, 10, 2):
        model.Add(where[(day, team)] >= 0).OnlyEnforceIf(count.NewBoolVar(f'first_wknd_home_or_bye_t{team}_d{day}'))
    model.Add(count >= 2)

# 6. Rival Matches
for team in range(n_teams):
    if rivals[teams[team]] is not None:
        rival_team = teams.index(rivals[teams[team]])
        model.Add(sum([match_config[(n_days-1, team, rival_team)], match_config[(n_days-1, rival_team, team)]]) == 1)
