from ortools.sat.python import cp_model
import json

# Model definition
model = cp_model.CpModel()

# Decision Variables
weights = [model.NewIntVar(1, 40, f'weight_{i}') for i in range(4)]
model.AddAllDifferent(weights)

# Constraints
for i in range(1, 41):
    possible_combinations = []
    for j in range(2**4):
        combination = [(j >> k) & 1 for k in range(4)]
        total_weight = sum([combination[k] * (1 if (j >> (k + 4)) & 1 else -1) * weights[k].Value() for k in range(4)])
        if total_weight == i:
            possible_combinations.append(combination)
    model.AddBoolOr([model.NewBoolVar(f'combo_{i}_{k}') for k in range(len(possible_combinations))])
    for k, combination in enumerate(possible_combinations):
        bool_var = model.NewBoolVar(f'combo_{i}_{k}')
        for index, value in enumerate(combination):
            if value == 1:
                model.Add(weights[index] >= 1).OnlyEnforceIf(bool_var)
            elif value == 0:
                model.Add(weights[index] == 0).OnlyEnforceIf(bool_var)
        model.Add(sum([bool_var * (1 if c else -1) * w for c, w in zip(combination, weights)]) == i).OnlyEnforceIf(bool_var)

# Since we are not minimizing or maximizing anything, we just need to find a feasible solution.
solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    solution = {
        'weights': sorted([solver.Value(w) for w in weights])
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
