# Input data
n = 5

# Model definition
model = cp_model.CpModel()

# Decision Variables
x = {}
for i in range(n):
    for j in range(n):
        x[(i, j)] = model.NewIntVar(1, n*n, f'x_{i}_{j}')

# Constraints
# Each number is used exactly once
for num in range(1, n*n + 1):
    model.Add(sum([x[(i, j)] == num for i in range(n) for j in range(n)]) == 1)

# Movement rules
for i in range(n):
    for j in range(n):
        for num in range(1, n*n):
            val = x[(i, j)] == num
            # Check all possible next positions according to the movement rules
            next_positions = []
            for di, dj in [(-3, 0), (3, 0), (0, -3), (0, 3)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < n:
                    next_positions.append(x[(ni, nj)])
            for di, dj in [(-2, -2), (-2, 2), (2, -2), (2, 2)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < n:
                    next_positions.append(x[(ni, nj)])
            model.Add(sum([next_pos == num + 1 for next_pos in next_positions]) >= val)

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    grid = [[solver.Value(x[(i, j)]) for j in range(n)] for i in range(n)]
    solution = {'x': grid}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
